package io.github.capozziv.digitalbanking.customer.bootstrap

import io.github.capozziv.digitalbanking.customer.bootstrap.web.ApiClient
import org.assertj.core.api.Assertions.assertThat
import org.junit.jupiter.api.Test
import org.springframework.boot.test.web.server.LocalServerPort
import tools.jackson.databind.JsonNode

/** The OpenAPI contract generated by springdoc documents the five operations of the spec, their errors and the bearer scheme. */
class OpenApiIntegrationTest : CustomerIntegrationTest() {
    @LocalServerPort
    private var port: Int = 0

    private val docs: JsonNode by lazy {
        val response = ApiClient(port).get("/v3/api-docs")
        assertThat(response.status).describedAs(response.rawBody).isEqualTo(200)
        response.body!!
    }

    private fun operations(): Map<String, JsonNode> {
        val paths = docs.get("paths")
        return paths
            .propertyNames()
            .flatMap { path ->
                paths.get(path).propertyNames().map { method -> "${method.uppercase()} $path" to paths.get(path).get(method) }
            }.toMap()
    }

    @Test
    fun `the contract has exactly the five paths and methods of the spec`() {
        assertThat(operations().keys).containsExactlyInAnyOrder(
            "POST /customers",
            "GET /customers/me",
            "GET /admin/customers/{id}",
            "PUT /admin/customers/{id}/status",
            "GET /internal/customers/{id}",
        )
    }

    @Test
    fun `every operation documents 401, 403 and 500 as Problem Details`() {
        for ((name, operation) in operations()) {
            for (status in listOf("401", "403", "500")) {
                val response = operation.get("responses").get(status)
                assertThat(response).describedAs("$name $status").isNotNull()
                assertThat(response.get("content").get("application/problem+json")).describedAs("$name $status").isNotNull()
            }
        }
    }

    @Test
    fun `the bearerAuth scheme is declared and required`() {
        val scheme = docs.get("components").get("securitySchemes").get("bearerAuth")

        assertThat(scheme.get("type").asString()).isEqualTo("http")
        assertThat(scheme.get("scheme").asString()).isEqualTo("bearer")
        assertThat(scheme.get("bearerFormat").asString()).isEqualTo("JWT")
        assertThat(docs.get("security").toString()).contains("bearerAuth")
    }

    @Test
    fun `registering documents 201, 200 and 400 and the lookups document 404`() {
        val operations = operations()

        assertThat(operations.getValue("POST /customers").get("responses").propertyNames()).contains("201", "200", "400")
        for (name in listOf(
            "GET /customers/me",
            "GET /admin/customers/{id}",
            "PUT /admin/customers/{id}/status",
            "GET /internal/customers/{id}",
        )) {
            assertThat(operations.getValue(name).get("responses").propertyNames()).describedAs(name).contains("404")
        }
        assertThat(operations.getValue("PUT /admin/customers/{id}/status").get("responses").propertyNames()).contains("400")
    }
}
